"""Skeptic check 1 (independent of common.py / q21 / q22): figurate families mod 2^k and dropping classes.

Different code path from the researcher's scripts:
  * class labels are computed by iterating ALL residues mod 2^K at once with the working modulus
    shrinking by one bit per step (T^k(r) is well defined mod 2^(K-k));
  * N(k) is computed a second way, by a dynamic programme over admissible parity words;
  * triangular numbers are generated by cumulative sums, fibres are enumerated explicitly.

Conventions: shortcut map T(n) = n/2 | (q n + d)/2.  k = Terras stopping time (T-steps), class = residues
mod 2^k with coefficient stopping time exactly k (first k with q^s < 2^k).  Repo Set index = k + s.

Run: C:/repos/collatz/.venv/Scripts/python.exe -X utf8 v1_residues_classes.py
"""
import json
import os
import sys
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
LOG = open(os.path.join(HERE, "v1_residues_classes.log"), "w", encoding="utf-8")
RES = {}
T0 = time.time()


def out(*a):
    s = " ".join(str(x) for x in a)
    print(s)
    LOG.write(s + "\n")
    LOG.flush()


# OEIS A100982, typed from https://oeis.org/A100982 (not from common.py)
A100982 = [1, 1, 2, 3, 7, 12, 30, 85, 173, 476, 961, 2652, 8045, 17637, 51033, 108950, 312455]
# OEIS A023105 (number of distinct quadratic residues mod 2^n, n >= 0)
A023105 = [1, 2, 2, 3, 4, 7, 12, 23, 44, 87, 172, 343, 684, 1367, 2732, 5463, 10924, 21847, 43692,
           87383, 174764, 349527, 699052, 1398103, 2796204]


def smax_table(K, q):
    """smax[k] = largest s with q^s < 2^k (exact integers)."""
    t = [0] * (K + 1)
    for k in range(1, K + 1):
        s = 0
        while q ** (s + 1) < (1 << k):
            s += 1
        t[k] = s
    return t


def class_labels(K, q=3, d=1):
    """lab[r] = coefficient stopping time of r mod 2^K (0 if > K), all residues at once."""
    M = 1 << K
    x = np.arange(M, dtype=np.int64)
    s = np.zeros(M, dtype=np.int64)
    lab = np.zeros(M, dtype=np.int64)
    alive = np.ones(M, dtype=bool)
    sm = smax_table(K, q)
    for k in range(1, K + 1):
        odd = (x & 1) == 1
        x = np.where(odd, (q * x + d) >> 1, x >> 1)
        x &= (1 << (K - k)) - 1            # T^k(r) is determined mod 2^(K-k) only
        s += odd
        drop = alive & (s <= sm[k])
        lab[drop] = k
        alive &= ~drop
    return lab


def N_by_dp(K, q=3):
    """N(k) = number of parity words of length k whose first drop (q^s < 2^j) is at j = k.
    Words <-> residues mod 2^k bijectively (Terras/Everett), for every odd q and d."""
    sm = smax_table(K, q)
    alive = {0: 1}          # s -> number of words of the current length that have not dropped
    N = {}
    for k in range(1, K + 1):
        new = {}
        for s, c in alive.items():
            for b in (0, 1):
                new[s + b] = new.get(s + b, 0) + c
        dropped = sum(c for s, c in new.items() if s <= sm[k])
        if dropped:
            N[k] = dropped
        alive = {s: c for s, c in new.items() if s > sm[k]}
    return N


# ---------------------------------------------------------------------------------------------
out("=" * 100)
out("A. Triangular numbers mod 2^k: CRS on [0,2^k), fibres, windows, negative indices")
out("=" * 100)
ok_crs = True
for k in range(0, 25):
    M = 1 << k
    t = np.cumsum(np.arange(M, dtype=np.int64)) & (M - 1)     # T_0..T_(M-1) by cumulative sums
    ok_crs &= (np.sort(t) == np.arange(M)).all()
out("  T_0..T_(2^k-1) is a CRS mod 2^k for k = 0..24 (cumsum generation):", bool(ok_crs))
ok_fib = True
for k in range(0, 14):
    M, M2 = 1 << k, 1 << (k + 1)
    fib = {}
    for n in range(M2):
        fib.setdefault((n * (n + 1) // 2) % M, []).append(n)
    ok_fib &= len(fib) == M and all(len(v) == 2 and v[0] + v[1] == M2 - 1 for v in fib.values())
out("  Z/2^(k+1) -> Z/2^k is onto, exactly 2-to-1, fibres {n, 2^(k+1)-1-n}, k = 0..13:", ok_fib)
# windows [a, a+2^k): CRS iff a = 0 mod 2^k  (so 'the first 2^k triangular numbers' must start at T_0)
ok_win = True
bad_example = None
for k in range(1, 10):
    M = 1 << k
    for a in range(-2 * M, 2 * M + 1):
        vals = {(n * (n + 1) // 2) % M for n in range(a, a + M)}
        is_crs = len(vals) == M
        if is_crs != (a % M == 0):
            ok_win = False
        if a == 1 and k == 3:
            bad_example = sorted((n * (n + 1) // 2) % M for n in range(1, M + 1))
out("  window [a, a+2^k) is a CRS mod 2^k  <=>  a = 0 mod 2^k   (k = 1..9, -2^(k+1) <= a <= 2^(k+1)):", ok_win)
out("     e.g. T_1..T_8 mod 8 =", bad_example, " (not a CRS: the count must start at T_0 = 0)")
ok_neg = all(((-1 - n) * (-n) // 2) == n * (n + 1) // 2 for n in range(-5000, 5000))
out("  T_(-1-n) = T_n for -5000 <= n < 5000:", ok_neg)
RES["A"] = dict(crs=bool(ok_crs), fibres=ok_fib, windows=ok_win, neg=ok_neg)

# ---------------------------------------------------------------------------------------------
out("")
out("=" * 100)
out("B. Class counts N(k): residue iteration (K = 20) versus word DP versus OEIS A100982")
out("=" * 100)
K = 20
lab31 = class_labels(K, 3, 1)
cnt = np.bincount(lab31, minlength=K + 1)
N_res = {k: int(cnt[k]) >> (K - k) for k in range(1, K + 1) if cnt[k]}
N_dp = N_by_dp(K, 3)
ks = sorted(N_res)
oe = [1] + A100982
ok_N = N_res == N_dp and [N_res[k] for k in ks] == oe[:len(ks)]
ok_div = all(int(cnt[k]) % (1 << (K - k)) == 0 for k in ks)
out("  k (A020914):", ks)
out("  N(k)       :", [N_res[k] for k in ks])
out("  residue count = DP count = [1] + A100982 :", ok_N, "  counts divisible by 2^(K-k):", ok_div)
out("  undetermined residues mod 2^20:", int(cnt[0]))
RES["B"] = dict(N={str(k): N_res[k] for k in ks}, ok=bool(ok_N))
# the class is a union of residue classes mod 2^k: lab constant on r mod 2^k
ok_union = True
for k in ks:
    sel = np.nonzero(lab31 == k)[0]
    base = np.unique(sel & ((1 << k) - 1))
    ok_union &= len(base) == N_res[k] and len(sel) == N_res[k] << (K - k)
out("  each class k is a union of exactly N(k) residue classes mod 2^k:", bool(ok_union))

