out("")
out("=" * 100)
out("C. Residue-level class counts along the families, one full period, for FIVE rules")
out("   'natural' means: counts equal (period / 2^K) * (natural counts) for EVERY class incl. undetermined")
out("   '#classes' = number of distinct determined classes (k <= K) met by the family")
out("=" * 100)
K = 16
M = 1 << K
n1 = np.arange(M, dtype=np.int64)            # one period for integer-coefficient polynomials
n2 = np.arange(2 * M, dtype=np.int64)        # one period for the families with a 1/2


def tri(n):
    return (n * (n + 1) // 2) % M


def poly(s):
    return lambda n: ((s - 2) * n * n - (s - 4) * n) // 2 % M


FAMS = {
    "T_n": (tri, n2, 2),
    "n^2": (lambda n: n * n % M, n1, 1),
    "n^3": (lambda n: (n * n % M) * n % M, n1, 1),
    "T_n^2": (lambda n: tri(n) * tri(n) % M, n2, 2),
    "pentagonal s=5": (poly(5), n2, 2),
    "hexagonal s=6": (poly(6), n1, 1),
    "octagonal s=8": (poly(8), n1, 1),
    "dodecagonal s=12": (poly(12), n1, 1),
}
RULES = [(3, 1), (3, -1), (5, 1), (5, -1), (7, 1)]
RES["C"] = {}
for (q, d) in RULES:
    lab = class_labels(K, q, d)
    nat = np.bincount(lab, minlength=K + 1)
    out(f"  rule {q}x{d:+d}:  classes k = {[k for k in range(1, K + 1) if nat[k]][:8]}...,"
        f" undetermined at K=16: {int(nat[0])} ({nat[0] / M:.4f})")
    row = {}
    for name, (f, dom, per) in FAMS.items():
        c = np.bincount(lab[f(dom)], minlength=K + 1)
        natural = bool((c == per * nat).all())
        ncl = int((c[1:] > 0).sum())
        top = sorted(((int(c[k]) / len(dom), k) for k in range(1, K + 1) if c[k]), reverse=True)[:4]
        row[name] = dict(natural=natural, n_classes=ncl, undetermined_share=float(c[0] / len(dom)))
        out(f"     {name:18s} natural: {natural!s:5s}  #classes met: {ncl:2d}   undetermined share {c[0] / len(dom):.4f}"
            f"   largest shares (share, k): {[(round(a, 4), k) for a, k in top]}")
    RES["C"][f"{q}x{d:+d}"] = row
out("  READ THIS: for 3x+1 the collapsed families (n^2, T_n^2, s = 0 mod 4) meet exactly 2 classes;")
out("  for 3x-1, 5x+-1, 7x+1 they do NOT: the two-class statement is rule- and sign-dependent.")

# why: which single residue class mod 4 / mod 8 is a dropping class for each rule
out("")
out("  the class of odd numbers that drops first, per rule (residues mod 2^k with k the 2nd Terras time):")
for (q, d) in RULES:
    lab = class_labels(8, q, d)
    kk = sorted(set(int(v) for v in lab if v))[1]
    rs = sorted(set(int(r) % (1 << kk) for r in np.nonzero(lab == kk)[0]))
    out(f"     {q}x{d:+d}: k = {kk}, residues mod 2^{kk}: {rs}   (odd squares are 1 mod 8)")

