out("")
out("=" * 100)
out("D. Actual integers, 3x+1: Terras stopping time of T_n, n^2, n^3, T_n^2 for 0 <= n < 2^21")
out("   (wider than the researcher's 2^20; pure Python integers)")
out("=" * 100)


def stop(n, q=3, d=1, cap=100000):
    x, k = n, 0
    while k < cap:
        x = (q * x + d) >> 1 if x & 1 else x >> 1
        k += 1
        if x < n:
            return k
    return None


KD = 21
LD = 1 << KD
N21 = N_by_dp(KD, 3)
RES["D"] = {}
for name, f in (("T_n", lambda n: n * (n + 1) // 2), ("n^2", lambda n: n * n),
                ("n^3", lambda n: n * n * n), ("T_n^2", lambda n: (n * (n + 1) // 2) ** 2)):
    h = {}
    nodrop = []
    for n in range(LD):
        k = stop(f(n))
        if k is None:
            nodrop.append(n)
        else:
            h[k] = h.get(k, 0) + 1
    if name in ("T_n", "n^3"):
        exact = all(h.get(k, 0) == (N21[k] << (KD - k)) - (1 if k in (1, 2) else 0) for k in N21)
        out(f"  {name:6s} non-dropping indices {nodrop};  count(k) = N(k) 2^(21-k) for all k <= 21"
            f" (minus the values 0, 1): {exact};  mass with k > 21: {sum(v for k, v in h.items() if k > KD)}")
        RES["D"][name] = dict(nodrop=nodrop, exact=exact)
    else:
        out(f"  {name:6s} non-dropping indices {nodrop};  histogram {dict(sorted(h.items()))}")
        RES["D"][name] = dict(nodrop=nodrop, hist={str(k): v for k, v in sorted(h.items())})

out("")
out("  Same families as seeds of the MIRROR map 3x-1 (actual integers, 2 <= n <= 200000):")
for name, f in (("n^2", lambda n: n * n), ("T_n^2", lambda n: (n * (n + 1) // 2) ** 2)):
    h = {}
    bad = 0
    for n in range(2, 200001):
        k = stop(f(n), 3, -1)
        if k is None:
            bad += 1
        else:
            h[k] = h.get(k, 0) + 1
    top = sorted(h.items(), key=lambda t: -t[1])[:8]
    out(f"  3x-1, {name:6s}: {len(h)} distinct stopping times, non-dropping {bad}; most common (k, count): {top}")
    RES["D"]["mirror " + name] = dict(distinct=len(h), top=top)

