out("")
out("=" * 100)
out("E. Squares and cubes mod 2^k")
out("=" * 100)
ok_sq = True
for k in range(0, 25):
    M_ = 1 << k
    x = np.arange(M_, dtype=np.int64)
    ok_sq &= len(np.unique(x * x & (M_ - 1))) == A023105[k]
    if k >= 1:
        ok_sq &= A023105[k] == ((1 << (k - 1)) + (4 if k % 2 == 0 else 5)) // 3
out("  #squares mod 2^k = A023105(k) = (2^(k-1)+4)/3 | (2^(k-1)+5)/3 for k = 0(1)..24:", bool(ok_sq))
ok_odd = True
for k in range(3, 21):
    M_ = 1 << k
    w = np.arange(1, M_, 2, dtype=np.int64)
    vals, mult = np.unique(w * w & (M_ - 1), return_counts=True)
    ok_odd &= (vals % 8 == 1).all() and len(vals) == M_ // 8 and (mult == 4).all()
out("  odd squares mod 2^k are exactly the residues 1 mod 8, each hit 4 times (k = 3..20):", bool(ok_odd))
# cubes: exhaustive isometry check on all pairs of odd residues mod 2^11
kk = 11
w = np.arange(1, 1 << kk, 2, dtype=np.int64)
A_, B_ = np.meshgrid(w, w)
D1 = (A_ - B_)
D3 = (A_ ** 3 - B_ ** 3)
mask = D1 != 0


def v2arr(z):
    z = np.abs(z)
    v = np.zeros(z.shape, dtype=np.int64)
    zz = z.copy()
    for _ in range(64):
        ev = (zz & 1) == 0
        ev &= zz != 0
        if not ev.any():
            break
        v += ev
        zz = np.where(ev, zz >> 1, zz)
    return v


ok_cube = bool((v2arr(D3[mask]) == v2arr(D1[mask])).all())
out("  v2(a^3 - b^3) = v2(a - b) for ALL pairs of distinct odd a, b < 2^11 (exhaustive):", ok_cube)
RES["E"] = dict(squares=bool(ok_sq), odd_squares=bool(ok_odd), cube_isometry=ok_cube)

out("")
out(f"done in {time.time() - T0:.1f} s")
